	/*
     * @param	event CreateAlertEvent
     */
    @EventHandler( payloadType=CreateAlertEvent.class )
    public void handle( CreateAlertEvent event) {
	    LOGGER.info("handling CreateAlertEvent - " + event );
	    Alert entity = new Alert();
            entity.setAlertId( event.getAlertId() );
            entity.setRaisedAt( event.getRaisedAt() );
            entity.setClearedAt( event.getClearedAt() );
            entity.setMessage( event.getMessage() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAlert( entity );
    }

    /*
     * @param	event UpdateAlertEvent
     */
    @EventHandler( payloadType=UpdateAlertEvent.class )
    public void handle( UpdateAlertEvent event) {
    	LOGGER.info("handling UpdateAlertEvent - " + event );
    	
	    Alert entity = new Alert();
            entity.setAlertId( event.getAlertId() );
            entity.setRaisedAt( event.getRaisedAt() );
            entity.setClearedAt( event.getClearedAt() );
            entity.setMessage( event.getMessage() );
            entity.setDevice( event.getDevice() );
            entity.setAlertRule( event.getAlertRule() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAlert( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAlert( entity );        
    }
    
