/**
 * emit to subscription queries of type FindAlert,
 * but only if the id matches
 *
 * @param		entity	Alert
 */
	protected void emitFindAlert( Alert entity ) {
		LOGGER.info("handling emitFindAlert" );
		
	    queryUpdateEmitter.emit(FindAlertQuery.class,
	                            query -> query.getFilter().getAlertId().equals(entity.getAlertId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAlert
	 * 
	 * @param		entity	Alert
	 */
	protected void emitFindAllAlert( Alert entity ) {
		LOGGER.info("handling emitFindAllAlert" );
		
	    queryUpdateEmitter.emit(FindAllAlertQuery.class,
	                            query -> true,
	                            entity);
	}

